    <!-- Iconify web component: deferred so it never blocks first paint/parsing -->

    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link rel="preconnect" href="https://api.aladhan.com" crossorigin>
    <link rel="preconnect" href="https://i.ibb.co.com" crossorigin>
    <!-- LCP candidate: start fetching the hero image as early as possible -->
    <link rel="preload" as="image" href="https://i.ibb.co.com/C55dNtLm/download-16.jpg" fetchpriority="high">
    <!-- Load Google Fonts without blocking first paint: fetch in the background,
         then swap it in as the real stylesheet once it's ready.
         PERF FIX: Amiri (large display headings) uses display=optional so a late
         font arrival is simply skipped instead of triggering a full-page reflow
         once it lands; Inter/IBM Plex Mono (body/UI text) keep display=swap since
         they need to always show real text. Splitting into two requests lets each
         family use its own display strategy. -->
    <link rel="preload" as="style"
        href="https://fonts.googleapis.com/css2?family=Amiri:wght@400;700&display=optional"
        onload="this.onload=null;this.rel='stylesheet'">
    <link rel="preload" as="style"
        href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=IBM+Plex+Mono:wght@400;500;600;700&display=swap"
        onload="this.onload=null;this.rel='stylesheet'">
    <noscript>
        <link href="https://fonts.googleapis.com/css2?family=Amiri:wght@400;700&display=optional" rel="stylesheet">
        <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=IBM+Plex+Mono:wght@400;500;600;700&display=swap"
            rel="stylesheet">
    </noscript>
    <style>
        * {
            font-family: 'Inter', system-ui, -apple-system, sans-serif;
        }

        /* PERF FIX: static gradient background — the previous version continuously
           animated a large fixed pseudo-element behind ~15 backdrop-blur elements,
           forcing the browser to recompute every blur on every frame (this was the
           main cause of the 2,241ms "Style & Layout" cost in Lighthouse). */
        .animated-bg { background: linear-gradient(120deg, #faf6ec 0%, #efe6d0 50%, #f5e9c4 100%); }

        .floating { animation: float 6s ease-in-out infinite; }

        @keyframes float {
            0% { transform: translateY(0px) rotate(0deg); }
            50% { transform: translateY(-15px) rotate(2deg); }
            100% { transform: translateY(0px) rotate(0deg); }
        }

        .float-delay-1 { animation-delay: 1s; }
        .float-delay-2 { animation-delay: 2.5s; }

        .prayer-card { transition: all 0.3s cubic-bezier(0.2, 0.9, 0.4, 1.1); }

        @media (hover: hover) and (pointer: fine) {
            .prayer-card:hover {
                transform: translateY(-8px) scale(1.02);
                box-shadow: 0 25px 35px -12px rgba(11, 61, 54, 0.2);
            }
        }

        .ripple-btn { position: relative; overflow: hidden; }

        .ripple-btn:after {
            content: '';
            position: absolute;
            top: 50%;
            left: 50%;
            width: 0;
            height: 0;
            border-radius: 50%;
            background: rgba(255, 255, 255, 0.3);
            transform: translate(-50%, -50%);
            transition: width 0.4s, height 0.4s;
        }

        @media (hover: hover) and (pointer: fine) {
            .ripple-btn:hover:after { width: 200%; height: 200%; }
        }

        /* PERF: navbar keeps its blur — it's a single fixed element, and the
           background behind it is now static, so the cost is a one-time paint
           rather than a per-frame recompute. */
        .glass-navbar {
            background: rgba(250, 246, 236, 0.9);
            backdrop-filter: blur(12px);
            border-bottom: 1px solid rgba(201, 162, 39, 0.25);
        }

        /* Composited version: expand+fade a pseudo-element ring with transform/opacity
           instead of animating box-shadow (also forces a repaint every frame). */
        @keyframes pulseGlowT {
            0% { transform: scale(1); opacity: 0.45; }
            70% { transform: scale(1.6); opacity: 0; }
            100% { transform: scale(1.6); opacity: 0; }
        }

        .pulse-countdown { position: relative; }
        .pulse-countdown::after {
            content: '';
            position: absolute;
            inset: 0;
            border-radius: 9999px;
            background: rgba(201, 162, 39, 0.45);
            animation: pulseGlowT 2s infinite;
            pointer-events: none;
        }

        .reveal {
            opacity: 0;
            transform: translateY(25px);
            transition: opacity 0.7s ease, transform 0.7s ease;
        }

        .reveal.visible { opacity: 1; transform: translateY(0); }

        .modal-backdrop { transition: opacity 0.3s ease; }

        .modal-container {
            transition: all 0.3s ease;
            transform: scale(0.95);
            opacity: 0;
        }

        .modal-container.active { transform: scale(1); opacity: 1; }

        ::-webkit-scrollbar { width: 8px; }
        ::-webkit-scrollbar-track { background: #efe6d0; }
        ::-webkit-scrollbar-thumb { background: #145c4f; border-radius: 20px; }

        .gallery-img { transition: transform 0.4s ease, box-shadow 0.3s ease; cursor: pointer; }
        @media (hover: hover) and (pointer: fine) {
            .gallery-img:hover { transform: scale(1.02) translateY(-5px); box-shadow: 0 20px 25px -12px rgba(11, 61, 54, 0.25); }
        }
        .mockup-badge { background: linear-gradient(135deg, #faf6ec 0%, #efe6d0 100%); }

        .font-display { font-family: 'Amiri', 'Georgia', serif; }
        .font-mono-brand { font-family: 'IBM Plex Mono', monospace; }

        .star-motif-deco {
            position: absolute;
            opacity: 0.14;
            animation: starSpin 70s linear infinite;
            pointer-events: none;
        }

        @keyframes starSpin {
            from { transform: rotate(0deg); }
            to { transform: rotate(360deg); }
        }

        #loginForm input, #registerForm input { font-size: 16px; }

        .deco-floating { display: none; }
        @media (min-width: 640px) {
            .deco-floating { display: block; }
        }

        /* Respect low-power / reduced-motion preference */
        @media (prefers-reduced-motion: reduce) {
            .floating, .pulse-countdown::after, .star-motif-deco, .reveal {
                animation: none !important;
                transition: none !important;
            }
        }

        /* Reserve image space up-front to avoid layout shift */
        img { max-width: 100%; height: auto; display: block; }

        /* PERF FIX: sections below the hero are off-screen on first paint.
           content-visibility: auto tells the browser to skip layout/paint work
           for their subtree until the user scrolls near them, which is the main
           remaining "Style & Layout" cost (galeri + fitur + CTA + footer all get
           laid out up-front otherwise). contain-intrinsic-size gives an estimated
           placeholder height so scrollbar/scroll-position doesn't jump. */
        section:not(:first-of-type) {
            content-visibility: auto;
            contain-intrinsic-size: auto 800px;
        }
        footer {
            content-visibility: auto;
            contain-intrinsic-size: auto 300px;
        }

        /* Inline SVG icons (replacing the old iconify-icon custom element) */
        svg.mdi-icon { display: inline-block; vertical-align: -0.125em; flex-shrink: 0; }

        /* PERF FIX: replaces Tailwind's transition-fast (which watches every
           animatable CSS property for changes) with an explicit, small property
           list. Cheaper for the browser to track and reduces Style & Layout work
           whenever any of these elements gets hovered/toggled. */
        .transition-fast {
            transition-property: transform, box-shadow, background-color, color, opacity;
            transition-timing-function: cubic-bezier(.4,0,.2,1);
            transition-duration: .3s;
        }
    </style>
</head>

