            <div class="bg-gradient-to-r from-gold-600 to-gold-500 px-6 py-4 flex justify-between items-center"><h3 class="text-white text-xl font-display font-bold flex items-center gap-2"><svg class="mdi-icon" width="24" height="24" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false"><path d="M15,14C12.33,14 7,15.33 7,18V20H23V18C23,15.33 17.67,14 15,14M6,10V7H4V10H1V12H4V15H6V12H9V10M15,12A4,4 0 0,0 19,8A4,4 0 0,0 15,4A4,4 0 0,0 11,8A4,4 0 0,0 15,12Z"/></svg> Daftar Akun Baru</h3><button class="close-modal text-white hover:text-teal-900 text-2xl leading-none">&times;</button></div>
            <div class="p-6"><form id="registerForm"><div class="mb-3"><label class="block text-gray-700 font-semibold mb-1">Nama Lengkap</label><input type="text" id="regFullname" required class="w-full px-4 py-2 border rounded-xl font-mono-brand"></div><div class="mb-3"><label class="block text-gray-700 font-semibold mb-1">Email</label><input type="email" id="regEmail" required class="w-full px-4 py-2 border rounded-xl font-mono-brand"></div><div class="mb-3"><label class="block text-gray-700 font-semibold mb-1">Kelas / Asal Sekolah</label><input type="text" id="regClass" required class="w-full px-4 py-2 border rounded-xl font-mono-brand"></div><div class="mb-4"><label class="block text-gray-700 font-semibold mb-1">Password</label><input type="password" id="regPassword" required class="w-full px-4 py-2 border rounded-xl font-mono-brand"></div><button type="submit" class="w-full bg-gold-600 hover:bg-gold-700 text-white font-bold py-2.5 rounded-xl transition flex items-center justify-center gap-2 min-h-[46px]"><svg class="mdi-icon" width="24" height="24" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false"><path d="M21.1,12.5L22.5,13.91L15.97,20.5L12.5,17L13.9,15.59L15.97,17.67L21.1,12.5M10,17L13,20H3V18C3,15.79 6.58,14 11,14L12.89,14.11L10,17M11,4A4,4 0 0,1 15,8A4,4 0 0,1 11,12A4,4 0 0,1 7,8A4,4 0 0,1 11,4Z"/></svg> Daftar Sekarang</button></form><p class="text-center text-sm text-gray-500 mt-4">Sudah punya akun? <button id="switchToLoginFromRegister" class="text-teal-700 font-semibold hover:underline">Login disini</button></p></div>
        </div>
    </div>

    <script>
        const LAT = -0.227819;
        const LNG = 100.626617;
        const METHOD = 20;
        const MDI_PATHS = {"mdi:weather-night": "M17.75,4.09L15.22,6.03L16.13,9.09L13.5,7.28L10.87,9.09L11.78,6.03L9.25,4.09L12.44,4L13.5,1L14.56,4L17.75,4.09M21.25,11L19.61,12.25L20.2,14.23L18.5,13.06L16.8,14.23L17.39,12.25L15.75,11L17.81,10.95L18.5,9L19.19,10.95L21.25,11M18.97,15.95C19.8,15.87 20.69,17.05 20.16,17.8C19.84,18.25 19.5,18.67 19.08,19.07C15.17,23 8.84,23 4.94,19.07C1.03,15.17 1.03,8.83 4.94,4.93C5.34,4.53 5.76,4.17 6.21,3.85C6.96,3.32 8.14,4.21 8.06,5.04C7.79,7.9 8.75,10.87 10.95,13.06C13.14,15.26 16.1,16.22 18.97,15.95M17.33,17.97C14.5,17.81 11.7,16.64 9.53,14.5C7.36,12.31 6.2,9.5 6.04,6.68C3.23,9.82 3.34,14.64 6.35,17.66C9.37,20.67 14.19,20.78 17.33,17.97Z", "mdi:weather-sunset-up": "M3,12H7A5,5 0 0,1 12,7A5,5 0 0,1 17,12H21A1,1 0 0,1 22,13A1,1 0 0,1 21,14H3A1,1 0 0,1 2,13A1,1 0 0,1 3,12M15,12A3,3 0 0,0 12,9A3,3 0 0,0 9,12H15M12,2L14.39,5.42C13.65,5.15 12.84,5 12,5C11.16,5 10.35,5.15 9.61,5.42L12,2M3.34,7L7.5,6.65C6.9,7.16 6.36,7.78 5.94,8.5C5.5,9.24 5.25,10 5.11,10.79L3.34,7M20.65,7L18.88,10.79C18.74,10 18.47,9.23 18.05,8.5C17.63,7.78 17.1,7.15 16.5,6.64L20.65,7M12.71,16.3L15.82,19.41C16.21,19.8 16.21,20.43 15.82,20.82C15.43,21.21 14.8,21.21 14.41,20.82L12,18.41L9.59,20.82C9.2,21.21 8.57,21.21 8.18,20.82C7.79,20.43 7.79,19.8 8.18,19.41L11.29,16.3C11.5,16.1 11.74,16 12,16C12.26,16 12.5,16.1 12.71,16.3Z", "mdi:sun-clock": "M18.1 9.3L19.6 6L15.5 5.6C16.1 6.1 16.6 6.7 17 7.5C17.3 8.1 17.5 8.6 17.7 9.2C17.2 9.1 16.6 9 16 9H15.6C14.8 7.2 13.1 6 11 6C8.2 6 6 8.2 6 11C6 13.1 7.2 14.8 9 15.6V16C9 19.9 12.1 23 16 23S23 19.9 23 16C23 12.9 20.9 10.2 18.1 9.3M16 21C13.2 21 11 18.8 11 16S13.2 11 16 11 21 13.2 21 16 18.8 21 16 21M16.5 16.2L19.4 17.9L18.6 19.1L15 17V12H16.5V16.2M11 4C10.2 4 9.4 4.2 8.6 4.4L11 1L13.4 4.4C12.6 4.2 11.8 4 11 4M4.9 14.5C5.3 15.2 5.9 15.9 6.5 16.4L2.4 16L4.2 12.2C4.3 13 4.5 13.8 4.9 14.5M4.1 9.8L2.3 6L6.5 5.7C5.9 6.2 5.4 6.8 4.9 7.5C4.5 8.2 4.2 9 4.1 9.8Z", "mdi:weather-sunset-down": "M3,12H7A5,5 0 0,1 12,7A5,5 0 0,1 17,12H21A1,1 0 0,1 22,13A1,1 0 0,1 21,14H3A1,1 0 0,1 2,13A1,1 0 0,1 3,12M15,12A3,3 0 0,0 12,9A3,3 0 0,0 9,12H15M12,2L14.39,5.42C13.65,5.15 12.84,5 12,5C11.16,5 10.35,5.15 9.61,5.42L12,2M3.34,7L7.5,6.65C6.9,7.16 6.36,7.78 5.94,8.5C5.5,9.24 5.25,10 5.11,10.79L3.34,7M20.65,7L18.88,10.79C18.74,10 18.47,9.23 18.05,8.5C17.63,7.78 17.1,7.15 16.5,6.64L20.65,7M12.71,20.71L15.82,17.6C16.21,17.21 16.21,16.57 15.82,16.18C15.43,15.79 14.8,15.79 14.41,16.18L12,18.59L9.59,16.18C9.2,15.79 8.57,15.79 8.18,16.18C7.79,16.57 7.79,17.21 8.18,17.6L11.29,20.71C11.5,20.9 11.74,21 12,21C12.26,21 12.5,20.9 12.71,20.71Z", "mdi:weather-sunset": "M3,12H7A5,5 0 0,1 12,7A5,5 0 0,1 17,12H21A1,1 0 0,1 22,13A1,1 0 0,1 21,14H3A1,1 0 0,1 2,13A1,1 0 0,1 3,12M5,16H19A1,1 0 0,1 20,17A1,1 0 0,1 19,18H5A1,1 0 0,1 4,17A1,1 0 0,1 5,16M17,20A1,1 0 0,1 18,21A1,1 0 0,1 17,22H7A1,1 0 0,1 6,21A1,1 0 0,1 7,20H17M15,12A3,3 0 0,0 12,9A3,3 0 0,0 9,12H15M12,2L14.39,5.42C13.65,5.15 12.84,5 12,5C11.16,5 10.35,5.15 9.61,5.42L12,2M3.34,7L7.5,6.65C6.9,7.16 6.36,7.78 5.94,8.5C5.5,9.24 5.25,10 5.11,10.79L3.34,7M20.65,7L18.88,10.79C18.74,10 18.47,9.23 18.05,8.5C17.63,7.78 17.1,7.15 16.5,6.64L20.65,7Z", "mdi:night-sky": "M12.3,2C12.2,2 12.1,2 12,2A10,10 0 0,0 2,12A10,10 0 0,0 12,22C15,22 16.7,21 18.5,19.5C13,21 8,17 8,12C8,7 13,3 18.5,4.5C16.86,2.86 14.62,1.96 12.3,2M16.8,6.2L15.3,9.7L11.6,10L14.5,12.5L13.6,16L16.8,14L20,16L19,12.5L22,10L18.3,9.7L16.8,6.2Z", "mdi:chevron-right-circle": "M22,12A10,10 0 0,1 12,22A10,10 0 0,1 2,12A10,10 0 0,1 12,2A10,10 0 0,1 22,12M10,18L16,12L10,6L8.6,7.4L13.2,12L8.6,16.6L10,18Z", "mdi:progress-clock": "M13,2.03V2.05L13,4.05C17.39,4.59 20.5,8.58 19.96,12.97C19.5,16.61 16.64,19.5 13,19.93V21.93C18.5,21.38 22.5,16.5 21.95,11C21.5,6.25 17.73,2.5 13,2.03M11,2.06C9.05,2.25 7.19,3 5.67,4.26L7.1,5.74C8.22,4.84 9.57,4.26 11,4.06V2.06M4.26,5.67C3,7.19 2.25,9.04 2.05,11H4.05C4.24,9.58 4.8,8.23 5.69,7.1L4.26,5.67M2.06,13C2.26,14.96 3.03,16.81 4.27,18.33L5.69,16.9C4.81,15.77 4.24,14.42 4.06,13H2.06M7.1,18.37L5.67,19.74C7.18,21 9.04,21.79 11,22V20C9.58,19.82 8.23,19.25 7.1,18.37M12.5,7V12.25L17,14.92L16.25,16.15L11,13V7H12.5Z"};
        function mdiSvg(icon, size, cls){ return `<svg class="${cls||''}" width="${size||24}" height="${size||24}" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false"><path d="${MDI_PATHS[icon]}"/></svg>`; }
        const prayersList = [{ key: 'Imsak', label: 'Imsak', icon: 'mdi:weather-night', bgColor: 'bg-teal-50/80', borderColor: 'border-teal-200' },{ key: 'Fajr', label: 'Subuh', icon: 'mdi:weather-sunset-up', bgColor: 'bg-gold-50/80', borderColor: 'border-gold-200' },{ key: 'Dhuhr', label: 'Dzuhur', icon: 'mdi:sun-clock', bgColor: 'bg-gold-50/80', borderColor: 'border-gold-200' },{ key: 'Asr', label: 'Ashar', icon: 'mdi:weather-sunset-down', bgColor: 'bg-gold-50/80', borderColor: 'border-gold-200' },{ key: 'Maghrib', label: 'Maghrib', icon: 'mdi:weather-sunset', bgColor: 'bg-rose-50/80', borderColor: 'border-rose-200' },{ key: 'Isha', label: 'Isya', icon: 'mdi:night-sky', bgColor: 'bg-teal-100/80', borderColor: 'border-teal-300' }];
        const order = ['Fajr', 'Dhuhr', 'Asr', 'Maghrib', 'Isha'];
        const loadingEl = document.getElementById('loadingPrayers');
        const errorEl = document.getElementById('errorMessage');
        const prayerContentEl = document.getElementById('prayerContent');
        const errorDetailSpan = document.getElementById('errorDetail');
        const retryBtn = document.getElementById('retryBtn');
        const gregorianSpan = document.getElementById('gregorianDate');
        const hijriSpan = document.getElementById('hijriDate');
        const prayerGrid = document.getElementById('prayerGrid');
        const nextPrayerName = document.getElementById('nextPrayerName');
        const nextPrayerTimeSpan = document.getElementById('nextPrayerTime');
        const timeRemainingSpan = document.getElementById('timeRemaining');
        function getCurrentWIBMinutes() { const now = new Date(); const formatter = new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Jakarta', hour: '2-digit', minute: '2-digit', hour12: false }); const parts = formatter.formatToParts(now); let h=0,m=0; for(const p of parts){ if(p.type==='hour') h=parseInt(p.value); if(p.type==='minute') m=parseInt(p.value); } return h*60+m; }
        function timeToMin(timeStr){ const [h,m]=timeStr.split(':').map(Number); return h*60+m; }
        function formatRemaining(currentMin,targetMin,isTomorrow=false){ let diff=targetMin-currentMin; if(isTomorrow && diff<0) diff+=1440; if(diff<=0) return "Waktu sholat! Segera absen."; const hours=Math.floor(diff/60); const mins=diff%60; if(hours===0) return `${mins} menit lagi`; if(hours>0 && mins===0) return `${hours} jam lagi`; return `${hours} jam ${mins} menit lagi`; }
        function getNextPrayerData(timings, nowMin){ for(let p of order){ const t=timings[p]; if(t && timeToMin(t)>nowMin) return { key:p, timeStr:t, isTomorrow:false, targetMin:timeToMin(t) }; } const first=order[0]; const firstTime=timings[first]; return { key:first, timeStr:firstTime, isTomorrow:true, targetMin:timeToMin(firstTime)+1440 }; }
        function renderPrayerCards(timings){ prayerGrid.innerHTML=''; prayersList.forEach(p=>{ let waktu=timings[p.key]||'--:--'; if(p.key==='Imsak' && !timings.Imsak) waktu='--:--'; const card=document.createElement('div'); card.className=`prayer-card ${p.bgColor} border ${p.borderColor} rounded-2xl p-5 shadow-md flex justify-between items-center`; card.innerHTML=`<div class="flex items-center gap-3"><div class="bg-white rounded-full p-2 shadow-sm">${mdiSvg(p.icon,28)}</div><div><p class="text-xs font-bold text-gray-500 uppercase">${p.label}</p><p class="text-2xl font-mono-brand font-bold text-gray-800">${waktu}</p></div></div>${mdiSvg("mdi:chevron-right-circle",24,"text-teal-500")}`; prayerGrid.appendChild(card); }); }
        let countdownInterval=null;
        function updateCountdown(timings){ if(!timings) return; const nowMin=getCurrentWIBMinutes(); const next=getNextPrayerData(timings,nowMin); let displayName=prayersList.find(p=>p.key===next.key)?.label||next.key; if(next.key==='Fajr') displayName='Subuh'; nextPrayerName.innerText=displayName; nextPrayerTimeSpan.innerText=next.timeStr; const remainingText=formatRemaining(nowMin,next.isTomorrow?next.targetMin:next.targetMin,next.isTomorrow); timeRemainingSpan.innerHTML=`${mdiSvg("mdi:progress-clock",16)} ${remainingText}`; }
        function startTimer(timings){ if(countdownInterval) clearInterval(countdownInterval); updateCountdown(timings); countdownInterval=setInterval(()=>updateCountdown(timings),30000); }
        async function fetchSchedule(){ try{ loadingEl.classList.remove('hidden'); errorEl.classList.add('hidden'); prayerContentEl.classList.add('hidden'); const today=new Date().toISOString().split('T')[0]; const url=`https://api.aladhan.com/v1/timings/${today}?latitude=${LAT}&longitude=${LNG}&method=${METHOD}`; const resp=await fetch(url); if(!resp.ok) throw new Error('Gagal mengambil data'); const json=await resp.json(); if(json.code!==200||!json.data) throw new Error('Format API error'); const timings=json.data.timings; const greg=json.data.date.readable; const hijriData=json.data.date.hijri; gregorianSpan.innerText=greg||new Date().toLocaleDateString('id-ID',{dateStyle:'full'}); hijriSpan.innerText=`${hijriData.day} ${hijriData.month.en} ${hijriData.year}`; renderPrayerCards(timings); startTimer(timings); loadingEl.classList.add('hidden'); prayerContentEl.classList.remove('hidden'); errorEl.classList.add('hidden'); }catch(err){ console.error(err); loadingEl.classList.add('hidden'); errorDetailSpan.innerText=err.message||'Gagal memuat'; errorEl.classList.remove('hidden'); prayerContentEl.classList.add('hidden'); if(countdownInterval) clearInterval(countdownInterval); } }
        retryBtn.addEventListener('click',fetchSchedule);
        const revealElements=document.querySelectorAll('.reveal'); const observer=new IntersectionObserver((entries)=>{ entries.forEach(entry=>{ if(entry.isIntersecting){ entry.target.classList.add('visible'); observer.unobserve(entry.target); } }); },{threshold:0.1}); revealElements.forEach(el=>observer.observe(el));
        document.getElementById('loginBtn')?.addEventListener('click',()=>window.location.href='/login');
        document.getElementById('registerBtn')?.addEventListener('click',()=>window.location.href='/register');
        document.getElementById('heroLoginBtn')?.addEventListener('click',()=>window.location.href='/login');
        document.getElementById('heroRegisterBtn')?.addEventListener('click',()=>window.location.href='/register');
        document.getElementById('ctaRegisterBtn')?.addEventListener('click',()=>window.location.href='/register');
        fetchSchedule();
    </script>
</body>
</html>